def max_water(heights: list[int]) -> int:
    left = 0
    right = len(heights) - 1
    max_area = 0
    while left < right:
        width = right - left
        max_area = max(max_area, min(heights[left], heights[right]) * width)
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
    return max_area
